1	/**
2	 * Guards the shared instruction blocks that live in
3	 * claude-plugins/autopilot/skills/shared-rules/references/. Each block is the single
4	 * source of truth for text several skills or agents need; consumers read the block at
5	 * runtime instead of carrying a copy (see sharedRulesInvocation.test.ts for that half).
6	 *
7	 * Two runtimes can read nothing at all, so they keep a literal inlined copy:
8	 * releaseNotesPrompt.ts is passed to the Anthropic API as a raw system prompt with no
9	 * tools, and the structured-output agents declare restrictive `tools` lists (expert-review
10	 * declares `tools: []`). Those copies are still single-sourced — this test asserts each is
11	 * byte-identical to its canonical block.
12	 *
13	 * Replaces referenceFormattingSync.test.ts, which guarded only the reference-formatting
14	 * block across ~25 inlined copies. RFC-0001 remains canonical for that one block: the
15	 * reference file is asserted equal to the RFC's own sentinel block, so the RFC cannot
16	 * silently degrade into a third mutable copy.
17	 *
18	 * Vacuous-pass defences, both deliberate: every extracted block must be non-empty and
19	 * above a minimum length (a missing sentinel would otherwise extract "" and compare
20	 * equal to another ""), and the retained-copy matrix is explicit test data rather than a
21	 * glob, so a dropped or newly added inlined copy fails loudly instead of shrinking the
22	 * matrix in silence.
23	 */
24	import { readdir, readFile } from "node:fs/promises";
25	import { basename, join } from "node:path";
26	
27	import { describe, expect, test } from "bun:test";
28	
29	const actionDir = join(import.meta.dirname, "..");
30	const repoRoot = join(actionDir, "..", "..", "..");
31	const referencesDir = join(
32	  repoRoot,
33	  "claude-plugins/autopilot/skills/shared-rules/references",
34	);
35	const rfcPath = join(repoRoot, "rfc/0001-reference-formatting.md");
36	const agentsDir = join(repoRoot, "claude-plugins/autopilot/agents");
37	const releasePrompt = join(
38	  repoRoot,
39	  ".github/actions/release-action/src/releaseNotesPrompt.ts",
40	);
41	
42	/** Shortest a real block can be; anything smaller means the extraction went wrong. */
43	const minBlockLength = 80;
44	
45	/** Reference file → the sentinel name delimiting its canonical block. */
46	const blockSentinels: Record<string, string> = {
47	  "reference-formatting.md": "ref-format",
48	  "askuserquestion-format.md": "auq-format",
49	  "repomix-snapshot.md": "repomix-snapshot",
50	  "agent-json-output.md": "agent-json",
51	  "linear-mcp-access.md": "linear-mcp",
52	  "pr-title-grammar.md": "pr-title-grammar",
53	  "pr-body-grammar.md": "pr-body-grammar",
54	};
55	
56	/**
57	 * Every place a block is still inlined because the runtime cannot read a file.
58	 * Explicit on purpose — see the vacuous-pass note in the file header.
59	 */
60	const retainedCopies: { block: string; file: string; unescapeBackticks?: boolean }[] = [
61	  // Raw Anthropic API system prompt: no Claude Code SDK, therefore no tools at all.
62	  { block: "reference-formatting.md", file: releasePrompt, unescapeBackticks: true },
63	  // Structured-output agents: each declares its own `tools`, and expert-review declares [].
64	  ...[
65	    "digest-branch-diff.md",
66	    "digest-repo-standards.md",
67	    "expert-review.md",
68	    "resolve-alert-context.md",
69	    "resolve-assignees.md",
70	    "resolve-issue-context.md",
71	    "search-codebase-todos.md",
72	  ].map((name) => ({ block: "agent-json-output.md", file: join(agentsDir, name) })),
73	];
74	
75	/** Extract the named sentinel-delimited block from `content`, trimmed; null when absent. */
76	function extractBlock(content: string, sentinel: string): string | null {
77	  const pattern = new RegExp(
78	    `<!-- ${sentinel}:start -->([\\s\\S]*?)<!-- ${sentinel}:end -->`,
79	  );
80	  return pattern.exec(content)?.[1].trim() ?? null;
81	}
82	
83	const canonical = new Map<string, string>();
84	for (const [file, sentinel] of Object.entries(blockSentinels)) {
85	  const block = extractBlock(await readFile(join(referencesDir, file), "utf8"), sentinel);
86	  if (block) canonical.set(file, block);
87	}
88	
89	describe("shared block canonicals", () => {
90	  test("every reference file on disk is registered", async () => {
91	    const onDisk = (await readdir(referencesDir)).filter((f) => f.endsWith(".md")).sort();
92	    expect(onDisk).toEqual(Object.keys(blockSentinels).sort());
93	  });
94	
95	  test.each(Object.keys(blockSentinels))("%s exposes a substantial block", (file) => {
96	    const block = canonical.get(file);
97	    expect(block).not.toBeNull();
98	    expect(block).toBeDefined();
99	    expect(block!.length).toBeGreaterThan(minBlockLength);
100	  });
101	
102	  test("RFC-0001 stays canonical for the reference-formatting block", async () => {
103	    const fromRfc = extractBlock(await readFile(rfcPath, "utf8"), "ref-format");
104	    expect(fromRfc).not.toBeNull();
105	    expect(fromRfc!.length).toBeGreaterThan(minBlockLength);
106	    expect(canonical.get("reference-formatting.md")).toBe(fromRfc!);
107	  });
108	});
109	
110	describe("retained inlined copies", () => {
111	  test.each(retainedCopies.map((c) => [basename(c.file), c] as const))(
112	    "%s inlines its block verbatim",
113	    async (_name, copy) => {
114	      const raw = await readFile(copy.file, "utf8");
115	      // Inside a template literal the block's backticks are escaped as \` in source.
116	      const source = copy.unescapeBackticks ? raw.replaceAll("\\`", "`") : raw;
117	      const sentinel = blockSentinels[copy.block];
118	      const inlined = extractBlock(source, sentinel);
119	      expect(inlined).not.toBeNull();
120	      expect(inlined).toBe(canonical.get(copy.block)!);
121	    },
122	  );
123	
124	  test("no agent carries the JSON block without being registered", async () => {
125	    const registered = new Set(
126	      retainedCopies.filter((c) => c.block === "agent-json-output.md").map((c) => basename(c.file)),
127	    );
128	    const carrying: string[] = [];
129	    for (const name of await readdir(agentsDir)) {
130	      if (!name.endsWith(".md")) continue;
131	      const raw = await readFile(join(agentsDir, name), "utf8");
132	      if (raw.includes("Output ONLY a single JSON object")) carrying.push(name);
133	    }
134	    expect(carrying.sort()).toEqual([...registered].sort());
135	  });
136	});
